Contract LoanProcessingSystemSystem::loanPayment(loanid:Integer): Boolean {
          definition:
          loan:Loan = Loan.allInstance()->any(o | o.LoanID = loanid), isOpen:Boolean = loan.oclIsTypeOf(Loan) and loan.Status = LoanStatus::LSOPEN

            precondition:
          loan.oclIsUndefined() = bool or isOpen = false

            postcondition:
          let updatedLoan:Loan in updatedLoan = loan, updatedLoan.RemainAmountToPay = updatedLoan.RemainAmountToPay - updatedLoan.RepaymentAmount and result = (isOpen)

        }
